-- Reachability is decided once, at ingest, and read; a SQL re-derivation already disagreed with the classifier.
-- Default 'unknown', never 'reachable': a row predating the column is unjudged, and unanswered must not read as safe.
-- No RLS statement: no table is created, so security_findings keeps its policies (__generate_rls_sql.sh --check stays fresh).
-- Column is GENERATED by `prisma migrate diff --script`; the index is hand-written in the 20261026140100 style.
ALTER TABLE "security_findings" ADD COLUMN     "reachability" VARCHAR NOT NULL DEFAULT 'unknown';

-- Partial (resolved_at IS NULL) because the filter only runs on the open set; last_seen DESC, id makes it index-only.
CREATE INDEX IF NOT EXISTS "security_findings_open_reachability_idx"
  ON "security_findings" ("reachability", "last_seen" DESC, "id")
  WHERE "resolved_at" IS NULL;
